37	/**
38	 * This class maintains DataNode peer metrics (e.g. numOps, AvgTime, etc.) for
39	 * various peer operations.
40	 */
41	@InterfaceAudience.Private
42	@InterfaceStability.Unstable
43	public class DataNodePeerMetrics {
44	
45	  public static final Logger LOG = LoggerFactory.getLogger(
46	      DataNodePeerMetrics.class);
47	
48	  private final MutableRollingAverages sendPacketDownstreamRollingAverages;
49	
50	  private final String name;
51	
52	
53	  private final OutlierDetector slowNodeDetector;
54	
55	  /**
56	   * Minimum number of packet send samples which are required to qualify
57	   * for outlier detection. If the number of samples is below this then
58	   * outlier detection is skipped.
59	   */
60	  private final long minOutlierDetectionSamples;
61	  /**
62	   * Threshold in milliseconds below which a DataNode is definitely not slow.
63	   */
64	  private final long lowThresholdMs;
65	  /**
66	   * Minimum number of nodes to run outlier detection.
67	   */
68	  private final long minOutlierDetectionNodes;
69	
70	  public DataNodePeerMetrics(final String name, Configuration conf) {
71	    this.name = name;
72	    minOutlierDetectionSamples = conf.getLong(
73	        DFS_DATANODE_PEER_METRICS_MIN_OUTLIER_DETECTION_SAMPLES_KEY,
74	        DFS_DATANODE_PEER_METRICS_MIN_OUTLIER_DETECTION_SAMPLES_DEFAULT);
75	    lowThresholdMs =
76	        conf.getLong(DFSConfigKeys.DFS_DATANODE_SLOWPEER_LOW_THRESHOLD_MS_KEY,
77	            DFSConfigKeys.DFS_DATANODE_SLOWPEER_LOW_THRESHOLD_MS_DEFAULT);
78	    minOutlierDetectionNodes =
79	        conf.getLong(DFSConfigKeys.DFS_DATANODE_MIN_OUTLIER_DETECTION_NODES_KEY,
80	            DFSConfigKeys.DFS_DATANODE_MIN_OUTLIER_DETECTION_NODES_DEFAULT);
81	    this.slowNodeDetector =
82	        new OutlierDetector(minOutlierDetectionNodes, lowThresholdMs);
83	    sendPacketDownstreamRollingAverages = new MutableRollingAverages("Time");
84	  }
85	
86	  public String name() {
87	    return name;
88	  }
89	
90	  long getMinOutlierDetectionSamples() {
91	    return minOutlierDetectionSamples;
92	  }
93	
94	  /**
95	   * Creates an instance of DataNodePeerMetrics, used for registration.
96	   */
97	  public static DataNodePeerMetrics create(String dnName, Configuration conf) {
98	    final String name = "DataNodePeerActivity-" + (dnName.isEmpty()
99	        ? "UndefinedDataNodeName" + ThreadLocalRandom.current().nextInt()
100	        : dnName.replace(':', '-'));
101	
102	    return new DataNodePeerMetrics(name, conf);
103	  }
104	
105	  /**
106	   * Adds invocation and elapsed time of SendPacketDownstream for peer.
107	   * <p>
108	   * The caller should pass in a well-formatted peerAddr. e.g.
109	   * "[192.168.1.110:1010]" is good. This will be translated into a full
110	   * qualified metric name, e.g. "[192.168.1.110:1010]AvgTime".
111	   * </p>
112	   */
113	  public void addSendPacketDownstream(
114	      final String peerAddr,
115	      final long elapsedMs) {
116	    sendPacketDownstreamRollingAverages.add(peerAddr, elapsedMs);
117	  }
118	
119	  /**
120	   * Dump SendPacketDownstreamRollingAvgTime metrics as JSON.
121	   */
122	  public String dumpSendPacketDownstreamAvgInfoAsJson() {
123	    final MetricsJsonBuilder builder = new MetricsJsonBuilder(null);
124	    sendPacketDownstreamRollingAverages.snapshot(builder, true);
125	    return builder.toString();
126	  }
127	
128	  /**
129	   * Collects states maintained in {@link ThreadLocal}, if any.
130	   */
131	  public void collectThreadLocalStates() {
132	    sendPacketDownstreamRollingAverages.collectThreadLocalStates();
133	  }
134	
135	  /**
136	   * Retrieve the set of dataNodes that look significantly slower
137	   * than their peers.
138	   */
139	  public Map<String, Double> getOutliers() {
140	    // This maps the metric name to the aggregate latency.
141	    // The metric name is the datanode ID.
142	    final Map<String, Double> stats =
143	        sendPacketDownstreamRollingAverages.getStats(
144	            minOutlierDetectionSamples);
145	    LOG.trace("DataNodePeerMetrics: Got stats: {}", stats);
146	
147	    return slowNodeDetector.getOutliers(stats);
148	  }
149	
150	  public MutableRollingAverages getSendPacketDownstreamRollingAverages() {
151	    return sendPacketDownstreamRollingAverages;
152	  }
153	}
