50	/**
51	 * <p>
52	 * This class maintains a group of rolling average metrics. It implements the
53	 * algorithm of rolling average, i.e. a number of sliding windows are kept to
54	 * roll over and evict old subsets of samples. Each window has a subset of
55	 * samples in a stream, where sub-sum and sub-total are collected. All sub-sums
56	 * and sub-totals in all windows will be aggregated to final-sum and final-total
57	 * used to compute final average, which is called rolling average.
58	 * </p>
59	 */
60	@InterfaceAudience.Public
61	@InterfaceStability.Evolving
62	public class MutableRollingAverages extends MutableMetric implements Closeable {
63	
64	  private MutableRatesWithAggregation innerMetrics =
65	      new MutableRatesWithAggregation();
66	
67	  @VisibleForTesting
68	  static final ScheduledExecutorService SCHEDULER = Executors
69	      .newScheduledThreadPool(1, new ThreadFactoryBuilder().setDaemon(true)
70	          .setNameFormat("MutableRollingAverages-%d").build());
71	
72	  private ScheduledFuture<?> scheduledTask = null;
73	
74	  @Nullable
75	  private Map<String, MutableRate> currentSnapshot;
76	
77	  private final String avgInfoNameTemplate;
78	  private final String avgInfoDescTemplate;
79	  private int numWindows;
80	
81	  /**
82	   * This class maintains sub-sum and sub-total of SampleStat.
83	   */
84	  private static class SumAndCount {
85	    private final double sum;
86	    private final long count;
87	    private final long snapshotTimeStamp;
88	
89	    /**
90	     * Constructor for {@link SumAndCount}.
91	     *
92	     * @param sum sub-sum in sliding windows
93	     * @param count sub-total in sliding windows
94	     * @param snapshotTimeStamp when is a new SampleStat snapshot.
95	     */
96	    SumAndCount(final double sum, final long count,
97	        final long snapshotTimeStamp) {
98	      this.sum = sum;
99	      this.count = count;
100	      this.snapshotTimeStamp = snapshotTimeStamp;
101	    }
102	
103	    public double getSum() {
104	      return sum;
105	    }
106	
107	    public long getCount() {
108	      return count;
109	    }
110	
111	    public long getSnapshotTimeStamp() {
112	      return snapshotTimeStamp;
113	    }
114	  }
115	
116	  /**
117	   * <p>
118	   * key: metric name
119	   * </p>
120	   * <p>
121	   * value: deque where sub-sums and sub-totals for sliding windows are
122	   * maintained.
123	   * </p>
124	   */
125	  private Map<String, LinkedBlockingDeque<SumAndCount>> averages =
126	      new ConcurrentHashMap<>();
127	
128	  private static final long WINDOW_SIZE_MS_DEFAULT = 300_000;
129	  private static final int NUM_WINDOWS_DEFAULT = 36;
130	
131	  /**
132	   * Time duration after which a record is considered stale.
133	   * {@link MutableRollingAverages} should be time-sensitive, and it should use
134	   * the time window length(i.e. NUM_WINDOWS_DEFAULT * WINDOW_SIZE_MS_DEFAULT)
135	   * as the valid time to make sure some too old record won't be use to compute
136	   * average.
137	   */
138	  private long recordValidityMs =
139	      NUM_WINDOWS_DEFAULT * WINDOW_SIZE_MS_DEFAULT;
140	
141	  /**
142	   * Constructor for {@link MutableRollingAverages}.
143	   * @param metricValueName
144	   */
145	  public MutableRollingAverages(String metricValueName) {
146	    if (metricValueName == null) {
147	      metricValueName = "";
148	    }
149	    avgInfoNameTemplate = "[%s]" + "RollingAvg" +
150	        StringUtils.capitalize(metricValueName);
151	    avgInfoDescTemplate = "Rolling average " +
152	        StringUtils.uncapitalize(metricValueName) +" for "+ "%s";
153	    numWindows = NUM_WINDOWS_DEFAULT;
154	    scheduledTask = SCHEDULER.scheduleAtFixedRate(new RatesRoller(this),
155	        WINDOW_SIZE_MS_DEFAULT, WINDOW_SIZE_MS_DEFAULT, TimeUnit.MILLISECONDS);
156	  }
157	
158	  /**
159	   * This method is for testing only to replace the scheduledTask.
160	   */
161	  @VisibleForTesting
162	  synchronized void replaceScheduledTask(int windows, long interval,
163	                                         TimeUnit timeUnit) {
164	    numWindows = windows;
165	    scheduledTask.cancel(true);
166	    scheduledTask = SCHEDULER.scheduleAtFixedRate(new RatesRoller(this),
167	        interval, interval, timeUnit);
168	  }
169	
170	  @Override
171	  public void snapshot(MetricsRecordBuilder builder, boolean all) {
172	    if (all || changed()) {
173	      for (final Entry<String, LinkedBlockingDeque<SumAndCount>> entry
174	          : averages.entrySet()) {
175	        final String name = entry.getKey();
176	        final MetricsInfo avgInfo = info(
177	            String.format(avgInfoNameTemplate, StringUtils.capitalize(name)),
178	            String.format(avgInfoDescTemplate, StringUtils.uncapitalize(name)));
179	        double totalSum = 0;
180	        long totalCount = 0;
181	
182	        for (final SumAndCount sumAndCount : entry.getValue()) {
183	          totalCount += sumAndCount.getCount();
184	          totalSum += sumAndCount.getSum();
185	        }
186	
187	        if (totalCount != 0) {
188	          builder.addGauge(avgInfo, totalSum / totalCount);
189	        }
190	      }
191	      if (changed()) {
192	        clearChanged();
193	      }
194	    }
195	  }
196	
197	  /**
198	   * Collects states maintained in {@link ThreadLocal}, if any.
199	   */
200	  public void collectThreadLocalStates() {
201	    innerMetrics.collectThreadLocalStates();
202	  }
203	
204	  /**
205	   * @param name
206	   *          name of metric
207	   * @param value
208	   *          value of metric
209	   */
210	  public void add(final String name, final long value) {
211	    innerMetrics.add(name, value);
212	  }
213	
214	  private static class RatesRoller implements Runnable {
215	    private final MutableRollingAverages parent;
216	
217	    RatesRoller(final MutableRollingAverages parent) {
218	      this.parent = parent;
219	    }
220	
221	    @Override
222	    public void run() {
223	      synchronized (parent) {
224	        final MetricsCollectorImpl mc = new MetricsCollectorImpl();
225	        final MetricsRecordBuilder rb = mc.addRecord("RatesRoller");
226	        /**
227	         * snapshot all metrics regardless of being changed or not, in case no
228	         * ops since last snapshot, we will get 0.
229	         */
230	        parent.innerMetrics.snapshot(rb, true);
231	        Preconditions.checkState(mc.getRecords().size() == 1,
232	            "There must be only one record and it's named with 'RatesRoller'");
233	
234	        parent.currentSnapshot = parent.innerMetrics.getGlobalMetrics();
235	        parent.rollOverAvgs();
236	      }
237	      parent.setChanged();
238	    }
239	  }
240	
241	  /**
242	   * Iterates over snapshot to capture all Avg metrics into rolling structure
243	   * {@link MutableRollingAverages#averages}.
244	   */
245	  private synchronized void rollOverAvgs() {
246	    if (currentSnapshot == null) {
247	      return;
248	    }
249	
250	    for (Map.Entry<String, MutableRate> entry : currentSnapshot.entrySet()) {
251	      final MutableRate rate = entry.getValue();
252	      final LinkedBlockingDeque<SumAndCount> deque = averages.computeIfAbsent(
253	          entry.getKey(),
254	          new Function<String, LinkedBlockingDeque<SumAndCount>>() {
255	            @Override
256	            public LinkedBlockingDeque<SumAndCount> apply(String k) {
257	              return new LinkedBlockingDeque<>(numWindows);
258	            }
259	          });
260	      final SumAndCount sumAndCount = new SumAndCount(
261	          rate.lastStat().total(),
262	          rate.lastStat().numSamples(),
263	          rate.getSnapshotTimeStamp());
264	      /* put newest sum and count to the end */
265	      if (!deque.offerLast(sumAndCount)) {
266	        deque.pollFirst();
267	        deque.offerLast(sumAndCount);
268	      }
269	    }
270	
271	    setChanged();
272	  }
273	
274	  @Override
275	  public void close() throws IOException {
276	    if (scheduledTask != null) {
277	      scheduledTask.cancel(false);
278	    }
279	    scheduledTask = null;
280	  }
281	
282	  /**
283	   * Retrieve a map of metric name {@literal ->} (aggregate).
284	   * Filter out entries that don't have at least minSamples.
285	   *
286	   * @return a map of peer DataNode Id to the average latency to that
287	   *         node seen over the measurement period.
288	   */
289	  public synchronized Map<String, Double> getStats(long minSamples) {
290	    final Map<String, Double> stats = new HashMap<>();
291	
292	    for (final Entry<String, LinkedBlockingDeque<SumAndCount>> entry
293	        : averages.entrySet()) {
294	      final String name = entry.getKey();
295	      double totalSum = 0;
296	      long totalCount = 0;
297	
298	      for (final SumAndCount sumAndCount : entry.getValue()) {
299	        if (Time.monotonicNow() - sumAndCount.getSnapshotTimeStamp()
300	            < recordValidityMs) {
301	          totalCount += sumAndCount.getCount();
302	          totalSum += sumAndCount.getSum();
303	        }
304	      }
305	
306	      if (totalCount > minSamples) {
307	        stats.put(name, totalSum / totalCount);
308	      }
309	    }
310	    return stats;
311	  }
312	
313	  /**
314	   * Use for test only.
315	   */
316	  @VisibleForTesting
317	  public synchronized void setRecordValidityMs(long value) {
318	    this.recordValidityMs = value;
319	  }
320	}
