45	  @Test(timeout = 30000)
46	  public void testGetSendPacketDownstreamAvgInfo() throws Exception {
47	    final int windowSize = 5; // 5s roll over interval
48	    final int numWindows = 2; // 2 rolling windows
49	    final int iterations = 3;
50	    final int numOpsPerIteration = 1000;
51	
52	    final Configuration conf = new HdfsConfiguration();
53	    conf.setBoolean(DFS_DATANODE_PEER_STATS_ENABLED_KEY, true);
54	
55	    final DataNodePeerMetrics peerMetrics = DataNodePeerMetrics.create(
56	        "Sample-DataNode", conf);
57	    MetricsTestHelper.replaceRollingAveragesScheduler(
58	        peerMetrics.getSendPacketDownstreamRollingAverages(),
59	        numWindows, windowSize, TimeUnit.SECONDS);
60	    final long start = Time.monotonicNow();
61	    for (int i = 1; i <= iterations; i++) {
62	      final String peerAddr = genPeerAddress();
63	      for (int j = 1; j <= numOpsPerIteration; j++) {
64	        /* simulate to get latency of 1 to 1000 ms */
65	        final long latency = ThreadLocalRandom.current().nextLong(1, 1000);
66	        peerMetrics.addSendPacketDownstream(peerAddr, latency);
67	      }
68	
69	      /**
70	       * Sleep until 1s after the next windowSize seconds interval, to let the
71	       * metrics roll over
72	       */
73	      final long sleep = (start + (windowSize * 1000 * i) + 1000)
74	          - Time.monotonicNow();
75	      Thread.sleep(sleep);
76	
77	      /* dump avg info */
78	      final String json = peerMetrics.dumpSendPacketDownstreamAvgInfoAsJson();
79	
80	      /*
81	       * example json:
82	       * {"[185.164.159.81:9801]RollingAvgTime":504.867,
83	       *  "[49.236.149.246:9801]RollingAvgTime":504.463,
84	       *  "[84.125.113.65:9801]RollingAvgTime":497.954}
85	       */
86	      assertThat(json, containsString(peerAddr));
87	    }
88	  }
