90	  @Test(timeout = 30000)
91	  public void testRemoveStaleRecord() throws Exception {
92	    final int numWindows = 5;
93	    final long scheduleInterval = 1000;
94	    final int iterations = 3;
95	    final int numSamples = 100;
96	
97	    final Configuration conf = new HdfsConfiguration();
98	    conf.setLong(DFS_DATANODE_PEER_METRICS_MIN_OUTLIER_DETECTION_SAMPLES_KEY,
99	        numSamples);
100	    conf.setBoolean(DFS_DATANODE_PEER_STATS_ENABLED_KEY, true);
101	
102	    final DataNodePeerMetrics peerMetrics =
103	        DataNodePeerMetrics.create("Sample-DataNode", conf);
104	    MutableRollingAverages rollingAverages =
105	        peerMetrics.getSendPacketDownstreamRollingAverages();
106	    rollingAverages.setRecordValidityMs(numWindows * scheduleInterval);
107	    MetricsTestHelper.replaceRollingAveragesScheduler(rollingAverages,
108	        numWindows, scheduleInterval, TimeUnit.MILLISECONDS);
109	
110	    List<String> peerAddrList = new ArrayList<>();
111	    for (int i = 1; i <= iterations; i++) {
112	      peerAddrList.add(genPeerAddress());
113	    }
114	    for (String peerAddr : peerAddrList) {
115	      for (int j = 1; j <= numSamples; j++) {
116	        /* simulate to get latency of 1 to 1000 ms */
117	        final long latency = ThreadLocalRandom.current().nextLong(1, 1000);
118	        peerMetrics.addSendPacketDownstream(peerAddr, latency);
119	      }
120	    }
121	
122	    GenericTestUtils.waitFor(
123	        () -> rollingAverages.getStats(numSamples).size() > 0, 500, 5000);
124	    assertEquals(3, rollingAverages.getStats(numSamples).size());
125	    /* wait for stale report to be removed */
126	    GenericTestUtils.waitFor(
127	        () -> rollingAverages.getStats(numSamples).isEmpty(), 500, 10000);
128	    assertEquals(0, rollingAverages.getStats(numSamples).size());
129	
130	    /* dn can report peer metrics normally when it added back to cluster */
131	    for (String peerAddr : peerAddrList) {
